import csv
import hashlib
import importlib.util
import json
from pathlib import Path
import struct
import tempfile
import unittest

spec = importlib.util.spec_from_file_location('release', Path(__file__).parents[2] / 'tools/icon256_release.py')
release = importlib.util.module_from_spec(spec)
spec.loader.exec_module(release)


def image(version='1.2.3', name='ESP32_S3_Icon256', chip=9):
    h = bytearray(24)
    h[0], h[1], h[3], h[23] = 0xE9, 1, 0x2F, 1
    struct.pack_into('<H', h, 12, chip)
    name_hash = 5381
    for byte in name.encode():
        name_hash = (name_hash*33+byte) & 0xFFFFFFFF
    payload = b'\0'*256 + struct.pack('<II48s48sI3B', 0x57535453, 1, version.encode(), name.encode(), name_hash, 0, 15, 2)
    data = h + struct.pack('<II', 0x3C000020, len(payload)) + payload
    checksum = 0xEF
    for byte in payload:
        checksum ^= byte
    data += b'\0' * (15-len(data)%16) + bytes([checksum])
    return bytes(data) + hashlib.sha256(data).digest()


class ReleaseTests(unittest.TestCase):
    def test_channels_and_malicious_tags(self):
        self.assertEqual(release.version_from_tag('v1.2.3'), ('1.2.3', False))
        for suffix in ('beta.1', 'alpha.2', 'rc.1', 'devV5'):
            self.assertTrue(release.version_from_tag('v1.2.3-'+suffix)[1])
        for tag in ('1.2.3', 'v1.02.3', 'v1.2.3-beta.01', 'v1.2.3;echo hi', 'v1.2.3\n', 'v../main', 'v1.2.٣'):
            with self.subTest(tag=tag), self.assertRaises(ValueError):
                release.version_from_tag(tag)

    def test_prepare_updates_lock_and_package_consistently(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            (root/'package.json').write_text('{"version":"17.0.0-devV5"}')
            (root/'package-lock.json').write_text('{"version":"old","packages":{"":{"version":"old"}}}')
            release.prepare(root, 'v1.2.3-beta.1')
            self.assertEqual(json.loads((root/'package.json').read_text())['version'], '1.2.3-beta.1')
            lock = json.loads((root/'package-lock.json').read_text())
            self.assertEqual(lock['version'], lock['packages']['']['version'])

    def test_slot_limit_matches_tracked_partition_table(self):
        table = Path(__file__).parents[2] / 'tools/WLED_ESP32_4MB_1MB_FS.csv'
        rows = csv.reader(line for line in table.read_text().splitlines() if not line.startswith('#'))
        slots = [int(row[4].strip(), 0) for row in rows if len(row) > 4 and row[1].strip() == 'app']
        self.assertEqual(min(slots), release.MAX_APP_SIZE)

    def test_accepts_correct_image(self):
        release.inspect_firmware(image(), '1.2.3')

    def test_rejects_version_board_chip_and_corruption(self):
        for data in (image('1.2.4'), image(name='ESP32_S3_Rainbow'), image(chip=0),
                     image()[:-1], image()+b'\0', b'\0'*24, image()[:100]+b'x'+image()[101:],
                     b'x'*(release.MAX_APP_SIZE+1)):
            with self.subTest(length=len(data)), self.assertRaises(ValueError):
                release.inspect_firmware(data, '1.2.3')

    def test_manifest_roundtrip_and_tamper_rejection(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            binary = root/'firmware.bin'
            binary.write_bytes(image())
            out = root/'assets'
            manifest = release.package(binary, out, 'v1.2.3', 'ThingPulse/WLED-Icon256', 'a'*40)
            path = out/'manifest.json'
            release.verify(path)
            self.assertEqual(manifest['firmware']['size'], len(image()))
            self.assertEqual(manifest['firmware']['sha256'], hashlib.sha256(image()).hexdigest())
            for key, value in [('sha256','0'*64), ('size',1), ('target','rainbow'),
                               ('url','https://example.com/firmware.bin'), ('filename','../firmware.bin')]:
                altered = json.loads(json.dumps(manifest))
                altered['firmware'][key] = value
                path.write_text(json.dumps(altered))
                with self.subTest(key=key), self.assertRaises(ValueError):
                    release.verify(path)
            path.write_text(json.dumps(manifest))
            (out/'SHA256SUMS').write_text('tampered')
            with self.assertRaises(ValueError):
                release.verify(path)


if __name__ == '__main__':
    unittest.main()
